import{_ as t,o,c as a,a5 as n}from"./chunks/framework.BfQ7H7Qx.js";const m=JSON.parse('{"title":"FR 3.7.5 — Delete Brand Knowledge Document","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/06-ai-features/3-7-5-delete-brand-knowledge-document/spec.md","filePath":"feature/srs/06-ai-features/3-7-5-delete-brand-knowledge-document/spec.md"}'),d={name:"feature/srs/06-ai-features/3-7-5-delete-brand-knowledge-document/spec.md"};function r(s,e,i,c,l,g){return o(),a("div",null,[...e[0]||(e[0]=[n('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="fr-3-7-5-—-delete-brand-knowledge-document" tabindex="-1">FR 3.7.5 — Delete Brand Knowledge Document <a class="header-anchor" href="#fr-3-7-5-—-delete-brand-knowledge-document" aria-label="Permalink to &quot;FR 3.7.5 — Delete Brand Knowledge Document&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FR Code</strong></td><td style="text-align:left;"><code>3.7.5</code></td></tr><tr><td style="text-align:left;"><strong>Use Case ID</strong></td><td style="text-align:left;"><code>UC-092</code></td></tr><tr><td style="text-align:left;"><strong>Feature</strong></td><td style="text-align:left;">Delete Brand Knowledge Document</td></tr><tr><td style="text-align:left;"><strong>Domain</strong></td><td style="text-align:left;">AI Features (<code>3.7</code>)</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Client</code></td></tr><tr><td style="text-align:left;"><strong>Business Rules</strong></td><td style="text-align:left;"><code>BR-20</code>, <code>BR-46</code></td></tr><tr><td style="text-align:left;"><strong>Message Codes</strong></td><td style="text-align:left;"><code>MSG01</code>, <code>MSG03</code>, <code>MSG07</code></td></tr><tr><td style="text-align:left;"><strong>Status</strong></td><td style="text-align:left;">Implemented — Production Verified</td></tr></tbody></table><h2 id="_1-objective-business-value" tabindex="-1">1. Objective &amp; Business Value <a class="header-anchor" href="#_1-objective-business-value" aria-label="Permalink to &quot;1. Objective &amp; Business Value&quot;">​</a></h2><p>Enable authorized <code>Owner</code>, <code>Manager</code>, and <code>Client</code> actors to permanently remove obsolete or superseded Brand Knowledge documents from a Workspace (<code>BR-20</code>, <code>BR-46</code>), atomically purging all embedded vector chunks (<code>where={&quot;document_id&quot;: documentId}</code>) from ChromaDB (<code>brand_docs_{workspace_id}</code>), deleting the backing S3 object, releasing storage quota, and ensuring future AI prompts never cite outdated pricing or policies.</p><h2 id="_2-user-story" tabindex="-1">2. User Story <a class="header-anchor" href="#_2-user-story" aria-label="Permalink to &quot;2. User Story&quot;">​</a></h2><p>As an <code>Owner</code>, <code>Manager</code>, or <code>Client</code>, I want to delete an outdated Brand Guideline or product sheet from my Workspace Knowledge Base so that the AI Caption and Creative Studio immediately stops referencing retired brand claims while preserving previously generated historical Task content snapshots.</p><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance Criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Authorization &amp; Cross-Tenant Guard (<code>BR-20</code>):</strong> Only <code>Owner</code>, <code>Manager</code>, and <code>Client</code> members of <code>{workspaceId}</code> may invoke <code>DELETE /api/v1/workspaces/{workspaceId}/ai/knowledge/documents/{documentId}</code>. <code>Creator</code> and users from other Workspaces receive <code>403 FORBIDDEN</code> (<code>MSG07</code>), and <code>documentId</code> belonging to a different Workspace returns <code>404 NOT_FOUND</code> (<code>MSG01</code>).</li><li><strong>Complete Vector &amp; Storage Purge (<code>BR-46</code>):</strong> Deletion invokes <code>brandhub-ai-service</code> <code>DELETE /api/v1/ai/rag/documents/{documentId}</code> scoped to <code>brand_docs_{workspace_id}</code> to remove 100% of associated chunks, deletes the raw file in S3, and removes/archives metadata + updates <code>agency_storage_usage</code>.</li><li><strong>Historical Snapshot Preservation:</strong> Existing <code>ai_caption_generations</code> and <code>task_content_snapshots</code> that previously cited the deleted document remain intact for auditability; only new RAG retrievals exclude the purged vectors.</li><li><strong>Destructive Confirmation UX:</strong> Web UI presents a confirmation dialog displaying the document name and chunk count before executing <code>DELETE</code>.</li><li><strong>Internationalization (<code>vi.json</code> + <code>en.json</code>):</strong> Confirmation dialog title, warning copy, cancel/confirm buttons, and toast notifications use synchronized <code>aiStudio.knowledgeBase.delete.*</code> keys in <code>vi.json</code> and <code>en.json</code>.</li><li><strong>Light &amp; Dark Mode Compliance:</strong> Destructive confirmation modal and danger button tokens render with proper contrast in both Light and Dark themes.</li></ol><h2 id="_4-ui-ux-screen-states" tabindex="-1">4. UI / UX &amp; Screen States <a class="header-anchor" href="#_4-ui-ux-screen-states" aria-label="Permalink to &quot;4. UI / UX &amp; Screen States&quot;">​</a></h2><ul><li><strong>Web Surface:</strong> <code>DocumentList.tsx</code> row action menu + confirmation dialog on <code>/workspaces/:workspaceId/ai-studio/knowledge-base</code>.</li><li><strong>UI States:</strong><ul><li><strong>Confirming:</strong> Modal warns that AI generations will no longer ground on this document; Focus trap + <code>Escape</code> support.</li><li><strong>Deleting:</strong> Row spinner + disabled confirm button to prevent duplicate <code>DELETE</code> requests.</li><li><strong>Success:</strong> Document disappears from list, storage usage meter updates, localized success toast shown.</li><li><strong>Error:</strong> If ChromaDB purge fails (<code>MSG03</code>), document remains visible in retryable state so no silent zombie vectors remain in RAG.</li></ul></li></ul><h2 id="_5-api-contract" tabindex="-1">5. API Contract <a class="header-anchor" href="#_5-api-contract" aria-label="Permalink to &quot;5. API Contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Method &amp; Endpoint</th><th style="text-align:left;">Auth</th><th style="text-align:left;">Handler</th><th style="text-align:left;">Response</th></tr></thead><tbody><tr><td style="text-align:left;"><code>DELETE /api/v1/workspaces/{workspaceId}/ai/knowledge/documents/{documentId}</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Client</code>)</td><td style="text-align:left;">Business RAG service -&gt; <code>ai-service</code> <code>rag.py</code></td><td style="text-align:left;"><code>200 ApiResponse&lt;Void&gt;</code></td></tr><tr><td style="text-align:left;"><code>DELETE /api/v1/ai/rag/documents/{document_id}?workspace_id=...</code></td><td style="text-align:left;"><code>X-Internal-Api-Key</code></td><td style="text-align:left;"><code>VectorStoreService.delete_document_chunks()</code></td><td style="text-align:left;"><code>200 {&quot;deleted_chunks&quot;: N}</code></td></tr></tbody></table><h2 id="_6-error-handling-edge-cases" tabindex="-1">6. Error Handling &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-edge-cases" aria-label="Permalink to &quot;6. Error Handling &amp; Edge Cases&quot;">​</a></h2><ul><li><code>DOCUMENT_NOT_FOUND</code> (<code>404</code>, <code>MSG01</code>): Document already deleted or belongs to another Workspace.</li><li><code>FORBIDDEN</code> (<code>403</code>, <code>MSG07</code>): <code>Creator</code> attempts deletion or caller lacks Workspace membership.</li><li><code>VECTOR_PURGE_FAILED</code> (<code>503</code>, <code>MSG03</code>): ChromaDB unreachable; Business transaction aborts metadata deletion so operator/user can retry cleanly without leaving unreferenced vectors in ChromaDB.</li></ul><h2 id="_7-related-specifications-references" tabindex="-1">7. Related Specifications &amp; References <a class="header-anchor" href="#_7-related-specifications-references" aria-label="Permalink to &quot;7. Related Specifications &amp; References&quot;">​</a></h2><ul><li><strong>Sibling SRS FRs:</strong> <a href="./../3-7-3-view-brand-knowledge-documents/spec.html">FR 3.7.3 — View Brand Knowledge Documents</a> · <a href="./../3-7-4-upload-brand-knowledge-document/spec.html">FR 3.7.4 — Upload Brand Knowledge Document</a> · <a href="./../3-7-6-generate-caption/spec.html">FR 3.7.6 — Generate Caption</a></li><li><strong>Consolidated Extension Module:</strong> <a href="./../../../modules/05-ai-rag-and-crawler/rag-caption-moderation-and-humanizer/spec.html"><code>rag-caption-moderation-and-humanizer</code></a></li><li><strong>BA Domain Baseline:</strong> <a href="./../../../../ba/06-ai-features.html">BA 3.7 AI Features</a></li></ul><h2 id="_8-definition-of-done-out-of-scope" tabindex="-1">8. Definition of Done &amp; Out of Scope <a class="header-anchor" href="#_8-definition-of-done-out-of-scope" aria-label="Permalink to &quot;8. Definition of Done &amp; Out of Scope&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Verified zero residual chunks in ChromaDB after delete, S3 object cleanup, cross-workspace tamper rejection, <code>vi</code>/<code>en</code> i18n parity, and Light/Dark modal verification per <a href="./test.html">test.md</a>.</li><li><strong>Out of Scope:</strong> Soft-delete trash bin for RAG embeddings (Brand Knowledge deletions immediately stop grounding).</li></ul>',19)])])}const p=t(d,[["render",r]]);export{m as __pageData,p as default};
